// Provided for lab 8.1 (you do not edit this file): encodes the two comparison
// kernels of shared/tiled_cube.metal and shared/planes.metal.
#import <Metal/Metal.h>
#include <cstdint>

#include "../lab1_stencil3d/stencil.h"

// Fig. 8.8: one 8 x 8 x 8 threadgroup per 6 x 6 x 6 output tile.
void encodeStencilTiledCube(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                            id<MTLBuffer> in, id<MTLBuffer> out, uint32_t N, StencilCoeffs c) {
    [enc setComputePipelineState:pipeline];
    [enc setBuffer:in offset:0 atIndex:0];
    [enc setBuffer:out offset:0 atIndex:1];
    [enc setBytes:&N length:sizeof(N) atIndex:2];
    [enc setBytes:&c length:sizeof(c) atIndex:3];
    const NSUInteger inTile = 8, outTile = inTile - 2;
    const NSUInteger tiles = (N + outTile - 1) / outTile;
    [enc dispatchThreadgroups:MTLSizeMake(tiles, tiles, tiles)
        threadsPerThreadgroup:MTLSizeMake(inTile, inTile, inTile)];
}

// Fig. 8.10: one tileWidth x tileWidth threadgroup per (tileWidth - 2)^2 column of
// output, marching through tileWidth - 2 planes.
void encodeStencilPlanes(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                         id<MTLBuffer> in, id<MTLBuffer> out, uint32_t N, uint32_t tileWidth, StencilCoeffs c) {
    [enc setComputePipelineState:pipeline];
    [enc setBuffer:in offset:0 atIndex:0];
    [enc setBuffer:out offset:0 atIndex:1];
    [enc setBytes:&N length:sizeof(N) atIndex:2];
    [enc setBytes:&c length:sizeof(c) atIndex:3];
    const NSUInteger outTile = tileWidth - 2;
    const NSUInteger tiles = (N + outTile - 1) / outTile;
    [enc dispatchThreadgroups:MTLSizeMake(tiles, tiles, tiles)
        threadsPerThreadgroup:MTLSizeMake(tileWidth, tileWidth, 1)];
}
